-- Generated by scripts/build_compiled.py from src/fraudrules/rules/account-takeover/at-004-mfa-push-fatigue.yaml. Do not edit.
-- AT-004 Burst of denied or ignored MFA prompts for one customer
SELECT
  'AT-004' AS rule_id,
  'events' AS anchor_table,
  a.id AS anchor_id
FROM events AS a
JOIN events AS b
  ON b.customer_id = a.customer_id AND b.ts <= a.ts AND b.ts > a.ts - 600
WHERE
  (
    a.event_type = 'mfa_challenge' AND a.outcome IN ('denied', 'failure')
  )
  AND (
    b.event_type = 'mfa_challenge' AND b.outcome IN ('denied', 'failure')
  )
GROUP BY
  a.id
HAVING
  COUNT(*) >= 5;
